    handle: ?*anyopaque,
    src_data: [*]const ?[*]const u8,
    src_stride: [*]const c_int,
    dst_data: [*]const ?[*]u8,
    dst_stride: [*]const c_int,
) c_int {
    _ = src_data;
    _ = src_stride;
    _ = dst_data;
    _ = dst_stride;

    const ctx: *SwsContext = @ptrCast(@alignCast(handle orelse return -1));
    _ = ctx;

    // TODO: Implement pixel format conversion and scaling here.
