// filter.zig — scaler coefficient generation, bit-compatible with libswscale's
// initFilter() for the point / bilinear / bicubic kernels (filterAlign = 1).

const std = @import("std");

pub const Algo = enum { point, bilinear, bicubic };

pub const Filter = struct {
    size: usize,
    pos: []i32, // dstW entries
    coef: []i16, // dstW * size entries
    /// true when every output takes exactly src[i] with unity weight
    identity: bool,

    pub fn deinit(self: *Filter, a: std.mem.Allocator) void {
        a.free(self.pos);
        a.free(self.coef);
    }
};

fn avLog2(v: u32) i32 {
    if (v == 0) return 0;
    return 31 - @as(i32, @clz(v));
}

fn absI64(x: i64) i64 {
    return if (x < 0) -x else x;
}

fn roundedDiv(a: i64, b: i64) i64 {
    return if (a >= 0) @divTrunc(a + (b >> 1), b) else @divTrunc(a - (b >> 1), b);
}

pub fn init(a: std.mem.Allocator, xInc: i64, srcW_: i32, dstW_: i32, one: i64, algo: Algo, srcPos: i64, dstPos: i64) !Filter {
    const srcW: i64 = srcW_;
    const dstW: i64 = dstW_;
    const dw: usize = @intCast(dstW_);
    const fone: i64 = @as(i64, 1) << @intCast(54 - @min(avLog2(@intCast(@divTrunc(srcW_, dstW_))), 8));

    const pos = try a.alloc(i32, dw);
    errdefer a.free(pos);
    var filterSize: usize = 0;
    var filter: []i64 = undefined;

    if (absI64(xInc - 0x10000) < 10 and srcPos == dstPos) {
        filterSize = 1;
        filter = try a.alloc(i64, dw);
        for (0..dw) |i| {
            filter[i] = fone;
            pos[i] = @intCast(i);
        }
    } else if (algo == .point) {
        filterSize = 1;
        filter = try a.alloc(i64, dw);
        var xDstInSrc: i64 = ((dstPos * xInc) >> 8) - ((srcPos * 0x8000) >> 7);
        for (0..dw) |i| {
            const xx: i64 = (xDstInSrc - 0 + (1 << 15)) >> 16;
            pos[i] = @truncate(xx);
            filter[i] = fone;
            xDstInSrc += xInc;
        }
    } else {
        const sizeFactor: i64 = if (algo == .bicubic) 4 else 2;
        var fs: i64 = if (xInc <= 1 << 16) 1 + sizeFactor else 1 + @divTrunc(sizeFactor * srcW + dstW - 1, dstW);
        fs = @min(fs, srcW - 2);
        fs = @max(fs, 1);
        filterSize = @intCast(fs);
        filter = try a.alloc(i64, dw * filterSize);
        var xDstInSrc: i64 = ((dstPos * xInc) >> 7) - ((srcPos * 0x10000) >> 7);
        const B: i64 = 0;
        const C: i64 = 10066329; // (int64_t)(0.6 * (1 << 24))
        for (0..dw) |i| {
            var xx: i64 = @as(i32, @truncate(@divTrunc(xDstInSrc - (fs - 2) * (1 << 16), 1 << 17)));
            pos[i] = @truncate(xx);
            for (0..filterSize) |j| {
                var d: i64 = absI64(xx * (1 << 17) - xDstInSrc) << 13;
                if (xInc > 1 << 16) d = @divTrunc(d * dstW, srcW);
                var coeff: i64 = 0;
                if (algo == .bicubic) {
                    if (d >= @as(i64, 1) << 31) {
                        coeff = 0;
                    } else {
                        const dd = (d * d) >> 30;
                        const ddd = (dd * d) >> 30;
                        if (d < @as(i64, 1) << 30) {
                            coeff = (12 * (1 << 24) - 9 * B - 6 * C) * ddd +
                                (-18 * (1 << 24) + 12 * B + 6 * C) * dd +
                                (6 * (1 << 24) - 2 * B) * (1 << 30);
                        } else {
                            coeff = (-B - 6 * C) * ddd +
                                (6 * B + 30 * C) * dd +
                                (-12 * B - 48 * C) * d +
                                (8 * B + 24 * C) * (1 << 30);
                        }
                    }
                    coeff = @divTrunc(coeff, @divTrunc(@as(i64, 1) << 54, fone));
                } else {
                    coeff = (1 << 30) - d;
                    if (coeff < 0) coeff = 0;
                    coeff *= fone >> 30;
                }
                filter[i * filterSize + j] = coeff;
                xx += 1;
            }
            xDstInSrc += 2 * xInc;
        }
    }
    defer a.free(filter);

    // reduce step 1
    const f2s = filterSize;
    const filter2 = filter;
    var minFilterSize: usize = 0;
    const cutLimit: f64 = 0.002 * @as(f64, @floatFromInt(fone));
    var ii: isize = @as(isize, @intCast(dw)) - 1;
    while (ii >= 0) : (ii -= 1) {
        const i: usize = @intCast(ii);
        var min = f2s;
        var cutOff: i64 = 0;
        for (0..f2s) |_| {
            cutOff += absI64(filter2[i * f2s]);
            if (@as(f64, @floatFromInt(cutOff)) > cutLimit) break;
            if (i < dw - 1 and pos[i] >= pos[i + 1]) break;
            var k: usize = 1;
            while (k < f2s) : (k += 1) filter2[i * f2s + k - 1] = filter2[i * f2s + k];
            filter2[i * f2s + k - 1] = 0;
            pos[i] += 1;
        }
        cutOff = 0;
        var j: usize = f2s - 1;
        while (j > 0) : (j -= 1) {
            cutOff += absI64(filter2[i * f2s + j]);
            if (@as(f64, @floatFromInt(cutOff)) > cutLimit) break;
            min -= 1;
        }
        if (min > minFilterSize) minFilterSize = min;
    }
    const fsz = minFilterSize;
    const f = try a.alloc(i64, dw * fsz);
    defer a.free(f);
    for (0..dw) |i| {
        for (0..fsz) |j| {
            f[i * fsz + j] = if (j >= f2s) 0 else filter2[i * f2s + j];
        }
    }
    // fix borders
    const fszi: i64 = @intCast(fsz);
    for (0..dw) |i| {
        const row = f[i * fsz .. (i + 1) * fsz];
        if (pos[i] < 0) {
            var j: usize = 1;
            while (j < fsz) : (j += 1) {
                const left: usize = @intCast(@max(@as(i64, @intCast(j)) + pos[i], 0));
                row[left] += row[j];
                row[j] = 0;
            }
            pos[i] = 0;
        }
        if (@as(i64, pos[i]) + fszi > srcW) {
            const shift: i64 = @as(i64, pos[i]) + @min(fszi - srcW, 0);
            var acc: i64 = 0;
            var j: isize = @as(isize, @intCast(fsz)) - 1;
            while (j >= 0) : (j -= 1) {
                const ju: usize = @intCast(j);
                if (@as(i64, pos[i]) + j >= srcW) {
                    acc += row[ju];
                    row[ju] = 0;
                }
            }
            j = @as(isize, @intCast(fsz)) - 1;
            while (j >= 0) : (j -= 1) {
                const ju: usize = @intCast(j);
                if (j < shift) {
                    row[ju] = 0;
                } else {
                    row[ju] = row[@intCast(j - shift)];
                }
            }
            pos[i] -= @intCast(shift);
            row[@intCast(srcW - 1 - pos[i])] += acc;
        }
    }
    // normalize
    const coef = try a.alloc(i16, dw * fsz);
    for (0..dw) |i| {
        var sum: i64 = 0;
        for (0..fsz) |j| sum += f[i * fsz + j];
        sum = @divTrunc(sum + @divTrunc(one, 2), one);
        if (sum == 0) sum = 1;
        var err: i64 = 0;
        for (0..fsz) |j| {
            const v = f[i * fsz + j] + err;
            const intV = roundedDiv(v, sum);
            coef[i * fsz + j] = @truncate(intV);
            err = v - intV * sum;
        }
    }
    var identity = fsz == 1 and dstW_ == srcW_;
    if (identity) {
        for (0..dw) |i| {
            if (pos[i] != @as(i32, @intCast(i)) or coef[i] != one) {
                identity = false;
                break;
            }
        }
    }
    return .{ .size = fsz, .pos = pos, .coef = coef, .identity = identity };
}

