// main.zig — swscale candidate: C-ABI entry points and conversion dispatch.
//
// The conversion pipeline mirrors libswscale's C path (same filters, same
// fixed-point rounding) so output tracks the reference; the inner loops are
// written for @Vector / auto-vectorisation.

const std = @import("std");
const filter = @import("filter.zig");
const k = @import("kernels.zig");

const alloc = std.heap.c_allocator;

pub const YUV420P = 0;
pub const YUV422P = 1;
pub const YUV444P = 2;
pub const NV12 = 3;
pub const NV21 = 4;
pub const RGB24 = 5;
pub const BGR24 = 6;
pub const RGBA = 7;
pub const BGRA = 8;
pub const GRAY8 = 9;

fn isRGB(f: i32) bool {
    return f >= RGB24 and f <= BGRA;
}
fn isPlanarYUV(f: i32) bool {
    return f <= NV21;
}
fn isNV(f: i32) bool {
    return f == NV12 or f == NV21;
}
fn hSub(f: i32) u5 {
    return switch (f) {
        YUV420P, YUV422P, NV12, NV21 => 1,
        else => 0,
    };
}
fn vSub(f: i32) u5 {
    return switch (f) {
        YUV420P, NV12, NV21 => 1,
        else => 0,
    };
}
fn ceilShr(x: i32, s: u5) i32 {
    return -((-x) >> s);
}

const Mode = enum {
    rgb_shuffle,
    yuv2rgb_table,
    planar_copy,
    planar_to_nv,
    nv_to_planar,
    bgr24_to_yv12,
    generic,
};

pub const Ctx = struct {
    sw: i32,
    sh: i32,
    sf: i32,
    dw: i32,
    dh: i32,
    df: i32,
    mode: Mode,
    tabs: k.Tables,

    // generic pipeline
    hLum: filter.Filter = undefined,
    hChr: filter.Filter = undefined,
    vLum: filter.Filter = undefined,
    vChr: filter.Filter = undefined,
    chrSrcW: i32 = 0,
    chrSrcH: i32 = 0,
    chrDstW: i32 = 0,
    chrDstH: i32 = 0,
    chrSrcHSub: u5 = 0,
    chrSrcVSub: u5 = 0,
    chrDstHSub: u5 = 0,
    chrDstVSub: u5 = 0,
    fullChr: bool = false,
    needAlpha: bool = false,
    needChr: bool = false,
    lumStride: usize = 0,
    chrStride: usize = 0,
    lumBuf: []i16 = &.{},
    alpBuf: []i16 = &.{},
    uBuf: []i16 = &.{},
    vBuf: []i16 = &.{},
    lumDone: []bool = &.{},
    chrDone: []bool = &.{},
    tmp0: []i16 = &.{},
    tmp1: []i16 = &.{},
    tmp2: []i16 = &.{},
    tmpU8: []u8 = &.{},
    tmpV8: []u8 = &.{},
    grayChr: []i16 = &.{},
};

fn algoOf(a: c_int) filter.Algo {
    return switch (a) {
        0 => .point,
        2 => .bicubic,
        else => .bilinear,
    };
}

fn initGeneric(c: *Ctx, algo: filter.Algo) !void {
    const sf = c.sf;
    const df = c.df;
    c.chrSrcHSub = hSub(sf);
    c.chrSrcVSub = vSub(sf);
    c.chrDstHSub = hSub(df);
    c.chrDstVSub = vSub(df);
    if (isRGB(df)) {
        // full chroma interpolation when odd width or source chroma not subsampled
        c.fullChr = (c.dw & 1) != 0 or (c.chrSrcHSub == 0 and c.chrSrcVSub == 0);
        if (!c.fullChr) c.chrDstHSub = 1;
    }
    if (isRGB(sf) and (c.dw >> c.chrDstHSub) <= (c.sw >> 1)) c.chrSrcHSub = 1;
    c.chrSrcW = ceilShr(c.sw, c.chrSrcHSub);
    c.chrSrcH = ceilShr(c.sh, c.chrSrcVSub);
    c.chrDstW = ceilShr(c.dw, c.chrDstHSub);
    c.chrDstH = ceilShr(c.dh, c.chrDstVSub);
    c.needAlpha = (sf == RGBA or sf == BGRA) and (df == RGBA or df == BGRA);
    c.needChr = !(sf == GRAY8 or df == GRAY8);

    const lumXInc: i64 = @divTrunc((@as(i64, c.sw) << 16) + (c.dw >> 1), c.dw);
    const lumYInc: i64 = @divTrunc((@as(i64, c.sh) << 16) + (c.dh >> 1), c.dh);
    const chrXInc: i64 = @divTrunc((@as(i64, c.chrSrcW) << 16) + (c.chrDstW >> 1), c.chrDstW);
    const chrYInc: i64 = @divTrunc((@as(i64, c.chrSrcH) << 16) + (c.chrDstH >> 1), c.chrDstH);

    // get_local_pos() with the default (-513) chroma position is always 128
    c.hLum = try filter.init(alloc, lumXInc, c.sw, c.dw, 1 << 14, algo, 128, 128);
    c.hChr = try filter.init(alloc, chrXInc, c.chrSrcW, c.chrDstW, 1 << 14, algo, 128, 128);
    c.vLum = try filter.init(alloc, lumYInc, c.sh, c.dh, 1 << 12, algo, 128, 128);
    c.vChr = try filter.init(alloc, chrYInc, c.chrSrcH, c.chrDstH, 1 << 12, algo, 128, 128);

    c.lumStride = (@as(usize, @intCast(c.dw)) + 31) & ~@as(usize, 31);
    c.chrStride = (@as(usize, @intCast(c.chrDstW)) + 31) & ~@as(usize, 31);
    const sh: usize = @intCast(c.sh);
    const csh: usize = @intCast(c.chrSrcH);
    c.lumBuf = try alloc.alloc(i16, c.lumStride * sh);
    if (c.needAlpha) c.alpBuf = try alloc.alloc(i16, c.lumStride * sh);
    c.lumDone = try alloc.alloc(bool, sh);
    c.chrDone = try alloc.alloc(bool, csh);
    if (c.needChr and sf != GRAY8) {
        c.uBuf = try alloc.alloc(i16, c.chrStride * csh);
        c.vBuf = try alloc.alloc(i16, c.chrStride * csh);
    }
    c.grayChr = try alloc.alloc(i16, c.chrStride);
    @memset(c.grayChr, 1 << 14);
    const sw: usize = @intCast(c.sw);
    c.tmp0 = try alloc.alloc(i16, sw + 64);
    c.tmp1 = try alloc.alloc(i16, sw + 64);
    c.tmp2 = try alloc.alloc(i16, sw + 64);
    c.tmpU8 = try alloc.alloc(u8, sw + 64);
    c.tmpV8 = try alloc.alloc(u8, sw + 64);
}

export fn swscale_create(src_w: c_int, src_h: c_int, src_fmt: c_int, dst_w: c_int, dst_h: c_int, dst_fmt: c_int, algo: c_int) ?*anyopaque {
    if (src_fmt < 0 or src_fmt > 9 or dst_fmt < 0 or dst_fmt > 9) return null;
    if (src_w <= 0 or src_h <= 0 or dst_w <= 0 or dst_h <= 0) return null;
    const c = alloc.create(Ctx) catch return null;
    c.* = .{
        .sw = src_w,
        .sh = src_h,
        .sf = src_fmt,
        .dw = dst_w,
        .dh = dst_h,
        .df = dst_fmt,
        .mode = .generic,
        .tabs = k.Tables.init(dst_fmt),
    };
    const unscaled = src_w == dst_w and src_h == dst_h;
    const sf = src_fmt;
    const df = dst_fmt;
    if (unscaled) {
        if (sf == YUV420P and isNV(df)) c.mode = .planar_to_nv;
        if (isNV(sf) and df == YUV420P) c.mode = .nv_to_planar;
        if ((sf == YUV420P or sf == YUV422P) and isRGB(df) and (dst_h & 1) == 0) c.mode = .yuv2rgb_table;
        if (sf == BGR24 and df == YUV420P and (dst_w & 1) == 0) c.mode = .bgr24_to_yv12;
        if (isRGB(sf) and isRGB(df)) c.mode = .rgb_shuffle;
        if (sf == df or
            (isPlanarYUV(sf) and !isNV(sf) and df == GRAY8) or
            (isPlanarYUV(df) and !isNV(df) and sf == GRAY8) or
            (sf <= YUV444P and df <= YUV444P and hSub(sf) == hSub(df) and vSub(sf) == vSub(df)))
        {
            c.mode = if (isRGB(sf)) .rgb_shuffle else .planar_copy;
        }
    }
    if (c.mode == .generic) {
        initGeneric(c, algoOf(algo)) catch return null;
    }
    return @ptrCast(c);
}

export fn swscale_destroy(handle: ?*anyopaque) void {
    const c: *Ctx = @ptrCast(@alignCast(handle orelse return));
    if (c.mode == .generic) {
        c.hLum.deinit(alloc);
        c.hChr.deinit(alloc);
        c.vLum.deinit(alloc);
        c.vChr.deinit(alloc);
        alloc.free(c.lumBuf);
        if (c.alpBuf.len != 0) alloc.free(c.alpBuf);
        alloc.free(c.lumDone);
        alloc.free(c.chrDone);
        if (c.uBuf.len != 0) alloc.free(c.uBuf);
        if (c.vBuf.len != 0) alloc.free(c.vBuf);
        alloc.free(c.grayChr);
        alloc.free(c.tmp0);
        alloc.free(c.tmp1);
        alloc.free(c.tmp2);
        alloc.free(c.tmpU8);
        alloc.free(c.tmpV8);
    }
    alloc.destroy(c);
}

pub const Planes = struct {
    p: [4]?[*]const u8,
    s: [4]isize,
    pub fn row(self: Planes, i: usize, y: usize) [*]const u8 {
        return self.p[i].? + @as(usize, @intCast(@as(isize, @intCast(y)) * self.s[i]));
    }
};
pub const DPlanes = struct {
    p: [4]?[*]u8,
    s: [4]isize,
    pub fn row(self: DPlanes, i: usize, y: usize) [*]u8 {
        return self.p[i].? + @as(usize, @intCast(@as(isize, @intCast(y)) * self.s[i]));
    }
};

export fn swscale_process(handle: ?*anyopaque, src_data: [*]const ?[*]const u8, src_stride: [*]const c_int, dst_data: [*]const ?[*]u8, dst_stride: [*]const c_int) c_int {
    const c: *Ctx = @ptrCast(@alignCast(handle orelse return -1));
    var s: Planes = undefined;
    var d: DPlanes = undefined;
    for (0..4) |i| {
        s.p[i] = src_data[i];
        s.s[i] = src_stride[i];
        d.p[i] = dst_data[i];
        d.s[i] = dst_stride[i];
    }
    if (s.p[0] == null or d.p[0] == null) return -1;
    switch (c.mode) {
        .rgb_shuffle => k.rgbShuffle(c, s, d),
        .yuv2rgb_table => k.yuv2rgbTable(c, s, d),
        .planar_copy => planarCopy(c, s, d),
        .planar_to_nv => planarToNv(c, s, d),
        .nv_to_planar => nvToPlanar(c, s, d),
        .bgr24_to_yv12 => k.bgr24ToYv12(c, s, d),
        .generic => @import("generic.zig").run(c, s, d),
    }
    return 0;
}

fn planeDims(f: i32, w: i32, h: i32, plane: usize) [2]usize {
    if (plane == 0) return .{ @intCast(w), @intCast(h) };
    const cw = ceilShr(w, hSub(f));
    const ch = ceilShr(h, vSub(f));
    return .{ @intCast(cw), @intCast(ch) };
}

fn planarCopy(c: *Ctx, s: Planes, d: DPlanes) void {
    const nd: usize = if (c.df == GRAY8) 1 else 3;
    for (0..nd) |pl| {
        const dims = planeDims(c.df, c.dw, c.dh, pl);
        if (pl > 0 and c.sf == GRAY8) {
            for (0..dims[1]) |y| @memset(d.row(pl, y)[0..dims[0]], 128);
            continue;
        }
        for (0..dims[1]) |y| @memcpy(d.row(pl, y)[0..dims[0]], s.row(pl, y)[0..dims[0]]);
    }
}

fn planarToNv(c: *Ctx, s: Planes, d: DPlanes) void {
    const w: usize = @intCast(c.dw);
    const h: usize = @intCast(c.dh);
    for (0..h) |y| @memcpy(d.row(0, y)[0..w], s.row(0, y)[0..w]);
    const cw: usize = @intCast(ceilShr(c.dw, 1));
    const ch: usize = @intCast(ceilShr(c.dh, 1));
    const swap = c.df == NV21;
    for (0..ch) |y| {
        const u = s.row(1, y);
        const v = s.row(2, y);
        k.interleave(d.row(1, y), if (swap) v else u, if (swap) u else v, cw);
    }
}

fn nvToPlanar(c: *Ctx, s: Planes, d: DPlanes) void {
    const w: usize = @intCast(c.dw);
    const h: usize = @intCast(c.dh);
    for (0..h) |y| @memcpy(d.row(0, y)[0..w], s.row(0, y)[0..w]);
    const cw: usize = @intCast(ceilShr(c.dw, 1));
    const ch: usize = @intCast(ceilShr(c.dh, 1));
    const swap = c.sf == NV21;
    for (0..ch) |y| {
        const u = d.row(1, y);
        const v = d.row(2, y);
        k.deinterleave(if (swap) v else u, if (swap) u else v, s.row(1, y), cw);
    }
}

