// generic.zig — the scaled / format-changing pipeline:
//   input conversion -> horizontal filter (15-bit) -> vertical filter -> output.
// Every source line is horizontally scaled at most once per frame, on demand.

const std = @import("std");
const m = @import("main.zig");
const k = @import("kernels.zig");

const MAXTAPS = 128;

inline fn lumRow(c: *m.Ctx, r: usize) [*]i16 {
    return c.lumBuf.ptr + r * c.lumStride;
}
inline fn alpRow(c: *m.Ctx, r: usize) [*]i16 {
    return c.alpBuf.ptr + r * c.lumStride;
}
inline fn uRow(c: *m.Ctx, r: usize) [*]i16 {
    if (c.sf == m.GRAY8) return c.grayChr.ptr;
    return c.uBuf.ptr + r * c.chrStride;
}
inline fn vRow(c: *m.Ctx, r: usize) [*]i16 {
    if (c.sf == m.GRAY8) return c.grayChr.ptr;
    return c.vBuf.ptr + r * c.chrStride;
}

fn ensureLum(c: *m.Ctx, s: m.Planes, r: usize) void {
    if (c.lumDone[r]) return;
    c.lumDone[r] = true;
    const srow = s.row(0, r);
    const sw: usize = @intCast(c.sw);
    if (m.isRGBpub(c.sf)) {
        k.rgbToY(c.sf, c.tmp0.ptr, srow, sw, &c.tabs);
        k.hscale16(lumRow(c, r), c.tmp0.ptr, &c.hLum, @intCast(c.dw));
        if (c.needAlpha) {
            k.rgbToA(c.sf, c.tmp1.ptr, srow, sw);
            k.hscale16(alpRow(c, r), c.tmp1.ptr, &c.hLum, @intCast(c.dw));
        }
    } else {
        k.hscale8(lumRow(c, r), srow, &c.hLum, @intCast(c.dw));
    }
}

fn ensureChr(c: *m.Ctx, s: m.Planes, r: usize) void {
    if (c.sf == m.GRAY8) return;
    if (c.chrDone[r]) return;
    c.chrDone[r] = true;
    const cdw: usize = @intCast(c.chrDstW);
    const csw: usize = @intCast(c.chrSrcW);
    if (m.isRGBpub(c.sf)) {
        const srow = s.row(0, r);
        if (c.chrSrcHSub == 1) {
            k.rgbToUVHalf(c.sf, c.tmp1.ptr, c.tmp2.ptr, srow, csw, &c.tabs);
        } else {
            k.rgbToUV(c.sf, c.tmp1.ptr, c.tmp2.ptr, srow, csw, &c.tabs);
        }
        k.hscale16(uRow(c, r), c.tmp1.ptr, &c.hChr, cdw);
        k.hscale16(vRow(c, r), c.tmp2.ptr, &c.hChr, cdw);
    } else if (c.sf == m.NV12 or c.sf == m.NV21) {
        const srow = s.row(1, r);
        if (c.sf == m.NV12) k.deinterleave(c.tmpU8.ptr, c.tmpV8.ptr, srow, csw) else k.deinterleave(c.tmpV8.ptr, c.tmpU8.ptr, srow, csw);
        k.hscale8(uRow(c, r), c.tmpU8.ptr, &c.hChr, cdw);
        k.hscale8(vRow(c, r), c.tmpV8.ptr, &c.hChr, cdw);
    } else {
        k.hscale8(uRow(c, r), s.row(1, r), &c.hChr, cdw);
        k.hscale8(vRow(c, r), s.row(2, r), &c.hChr, cdw);
    }
}

pub fn run(c: *m.Ctx, s: m.Planes, d: m.DPlanes) void {
    @memset(c.lumDone, false);
    @memset(c.chrDone, false);
    const dh: usize = @intCast(c.dh);
    const dw: usize = @intCast(c.dw);
    const cdw: usize = @intCast(c.chrDstW);
    const lsz = c.vLum.size;
    const csz = c.vChr.size;
    var lrows: [MAXTAPS][*]const i16 = undefined;
    var arows: [MAXTAPS][*]const i16 = undefined;
    var urows: [MAXTAPS][*]const i16 = undefined;
    var vrows: [MAXTAPS][*]const i16 = undefined;
    const packed_out = m.isRGBpub(c.df);
    const p1ok = packed_out and lsz == 1 and csz <= 2;
    const p2ok = packed_out and lsz == 2 and csz == 2;

    for (0..dh) |y| {
        const lp: usize = @intCast(c.vLum.pos[y]);
        for (0..lsz) |j| {
            ensureLum(c, s, lp + j);
            lrows[j] = lumRow(c, lp + j);
            if (c.needAlpha) arows[j] = alpRow(c, lp + j);
        }
        const lc = c.vLum.coef[y * lsz ..][0..lsz];
        if (!packed_out) {
            k.vplane(d.row(0, y), lrows[0..lsz], lc, dw);
            if (!c.needChr) continue;
            const mask = (@as(usize, 1) << c.chrDstVSub) - 1;
            if ((y & mask) != 0) continue;
            const cy = y >> c.chrDstVSub;
            const cp: usize = @intCast(c.vChr.pos[cy]);
            for (0..csz) |j| {
                ensureChr(c, s, cp + j);
                urows[j] = uRow(c, cp + j);
                vrows[j] = vRow(c, cp + j);
            }
            const cc = c.vChr.coef[cy * csz ..][0..csz];
            if (c.df == m.NV12) {
                k.vnv(d.row(1, cy), urows[0..csz], vrows[0..csz], cc, cdw);
            } else if (c.df == m.NV21) {
                k.vnv(d.row(1, cy), vrows[0..csz], urows[0..csz], cc, cdw);
            } else {
                k.vplane(d.row(1, cy), urows[0..csz], cc, cdw);
                k.vplane(d.row(2, cy), vrows[0..csz], cc, cdw);
            }
            continue;
        }
        // packed RGB output; chroma row index == y (no vertical subsampling in RGB)
        const cy = y;
        const cp: usize = @intCast(c.vChr.pos[cy]);
        for (0..csz) |j| {
            ensureChr(c, s, cp + j);
            urows[j] = uRow(c, cp + j);
            vrows[j] = vRow(c, cp + j);
        }
        // packed1 may peek at the next chroma line
        if (csz == 1) {
            urows[1] = urows[0];
            vrows[1] = vrows[0];
        }
        const cc = c.vChr.coef[cy * csz ..][0..csz];
        const out = d.row(0, y);
        const ap: ?[]const [*]const i16 = if (c.needAlpha) arows[0..lsz] else null;
        if (p1ok and lsz == 1 and csz == 1) {
            k.packed1(c, out, lrows[0], urows[0..2], vrows[0..2], if (ap) |a| a[0] else null, dw, 0);
        } else if (p1ok and lsz == 1 and csz == 2 and @as(i32, cc[0]) + cc[1] == 4096 and cc[1] >= 0 and cc[1] <= 4096) {
            k.packed1(c, out, lrows[0], urows[0..2], vrows[0..2], if (ap) |a| a[0] else null, dw, cc[1]);
        } else if (p2ok and @as(i32, lc[0]) + lc[1] == 4096 and lc[1] >= 0 and lc[1] <= 4096 and
            @as(i32, cc[0]) + cc[1] == 4096 and cc[1] >= 0 and cc[1] <= 4096)
        {
            k.packed2(c, out, lrows[0..2], urows[0..2], vrows[0..2], ap, dw, lc[1], cc[1]);
        } else {
            k.packedX(c, out, lrows[0..lsz], lc, urows[0..csz], vrows[0..csz], cc, ap, dw);
        }
    }
}

