// kernels.zig — per-line conversion kernels and colour tables.

const std = @import("std");
const m = @import("main.zig");
const filter = @import("filter.zig");

pub const Tables = struct {
    ytab: [2048]u8,
    rOff: [256]i32,
    gU: [256]i32,
    gV: [256]i32,
    bOff: [256]i32,
    // full-chroma output coefficients
    yoff: i32,
    ycoef: i32,
    v2r: i32,
    v2g: i32,
    u2g: i32,
    u2b: i32,
    // rgb -> yuv input coefficients (RGB2YUV_SHIFT = 15)
    ry: i32,
    gy: i32,
    by: i32,
    ru: i32,
    gu: i32,
    bu: i32,
    rv: i32,
    gv: i32,
    bv: i32,

    fn roundToInt16(f: i64) i32 {
        const r: i64 = (f + (1 << 15)) >> 16;
        if (r < -0x7FFF) return -0x8000;
        if (r > 0x7FFF) return 0x7FFF;
        return @intCast(r);
    }

    fn coefF(v: f64) i32 {
        return @intFromFloat(@trunc(v * 219.0 / 255.0 * 32768.0 + 0.5));
    }
    fn coefC(v: f64) i32 {
        return @intFromFloat(@trunc(v * 224.0 / 255.0 * 32768.0 + 0.5));
    }

    pub fn init(df: i32) Tables {
        _ = df;
        var t: Tables = undefined;
        // ff_yuv2rgb_c_init_tables, limited range source, default (BT.601) coefficients
        var crv: i64 = 104597;
        var cbu: i64 = 132201;
        var cgu: i64 = -25675;
        var cgv: i64 = -53279;
        const cy: i64 = @divTrunc(@as(i64, 1 << 16) * 255, 219);
        const oy: i64 = 16 << 16;
        t.ycoef = roundToInt16(cy * (1 << 13));
        t.yoff = roundToInt16(oy * (1 << 9));
        t.v2r = roundToInt16(crv * (1 << 13));
        t.v2g = roundToInt16(cgv * (1 << 13));
        t.u2g = roundToInt16(cgu * (1 << 13));
        t.u2b = roundToInt16(cbu * (1 << 13));
        crv = @divTrunc(crv * (1 << 16) + 0x8000, cy);
        cbu = @divTrunc(cbu * (1 << 16) + 0x8000, cy);
        cgu = @divTrunc(cgu * (1 << 16) + 0x8000, cy);
        cgv = @divTrunc(cgv * (1 << 16) + 0x8000, cy);
        var yb: i64 = -(384 << 16) - 512 * cy - oy;
        for (0..2048) |i| {
            const v = (yb + 0x8000) >> 16;
            t.ytab[i] = @intCast(std.math.clamp(v, 0, 255));
            yb += cy;
        }
        const yoffs: i64 = 326 + 512;
        for (0..256) |i| {
            const v: i64 = @intCast(i);
            t.rOff[i] = @intCast(yoffs - (crv >> 9) + ((v * crv) >> 16));
            t.gU[i] = @intCast(yoffs - (cgu >> 9) + ((v * cgu) >> 16));
            t.bOff[i] = @intCast(yoffs - (cbu >> 9) + ((v * cbu) >> 16));
            t.gV[i] = @intCast(-(cgv >> 9) + ((v * cgv) >> 16));
        }
        t.by = coefF(0.114);
        t.bv = -coefC(0.081);
        t.bu = coefC(0.500);
        t.gy = coefF(0.587);
        t.gv = -coefC(0.419);
        t.gu = -coefC(0.331);
        t.ry = coefF(0.299);
        t.rv = coefC(0.500);
        t.ru = -coefC(0.169);
        return t;
    }
};

// ── format helpers ──────────────────────────────────────────────────────────

fn bpp(comptime f: i32) usize {
    return switch (f) {
        m.RGB24, m.BGR24 => 3,
        m.RGBA, m.BGRA => 4,
        else => 1,
    };
}
fn rIdx(comptime f: i32) usize {
    return switch (f) {
        m.RGB24, m.RGBA => 0,
        else => 2,
    };
}
fn bIdx(comptime f: i32) usize {
    return 2 - rIdx(f);
}

// ── packed RGB <-> packed RGB ───────────────────────────────────────────────

fn shuffleRow(comptime sf: i32, comptime df: i32, dst: [*]u8, src: [*]const u8, w: usize) void {
    const sb = comptime bpp(sf);
    const db = comptime bpp(df);
    if (sf == df) {
        @memcpy(dst[0 .. w * sb], src[0 .. w * sb]);
        return;
    }
    for (0..w) |x| {
        const s = src + x * sb;
        const d = dst + x * db;
        d[comptime rIdx(df)] = s[comptime rIdx(sf)];
        d[1] = s[1];
        d[comptime bIdx(df)] = s[comptime bIdx(sf)];
        if (db == 4) d[3] = if (sb == 4) s[3] else 255;
    }
}

pub fn rgbShuffle(c: *m.Ctx, s: m.Planes, d: m.DPlanes) void {
    const w: usize = @intCast(c.dw);
    const h: usize = @intCast(c.dh);
    inline for (.{ m.RGB24, m.BGR24, m.RGBA, m.BGRA }) |sf| {
        if (c.sf == sf) {
            inline for (.{ m.RGB24, m.BGR24, m.RGBA, m.BGRA }) |df| {
                if (c.df == df) {
                    for (0..h) |y| shuffleRow(sf, df, d.row(0, y), s.row(0, y), w);
                    return;
                }
            }
        }
    }
}

// ── unscaled planar YUV 4:2:0 / 4:2:2 -> packed RGB (table based) ───────────

fn yuv2rgbRow(comptime df: i32, t: *const Tables, dst: [*]u8, py: [*]const u8, pu: [*]const u8, pv: [*]const u8, w: usize) void {
    const db = comptime bpp(df);
    for (0..w) |x| {
        const Y: i32 = py[x];
        const U = pu[x >> 1];
        const V = pv[x >> 1];
        const d = dst + x * db;
        d[comptime rIdx(df)] = t.ytab[@intCast(Y + t.rOff[V])];
        d[1] = t.ytab[@intCast(Y + t.gU[U] + t.gV[V])];
        d[comptime bIdx(df)] = t.ytab[@intCast(Y + t.bOff[U])];
        if (db == 4) d[3] = 255;
    }
}

pub fn yuv2rgbTable(c: *m.Ctx, s: m.Planes, d: m.DPlanes) void {
    const w: usize = @intCast(c.dw);
    const h: usize = @intCast(c.dh);
    const vs: u5 = if (c.sf == m.YUV420P) 1 else 0;
    inline for (.{ m.RGB24, m.BGR24, m.RGBA, m.BGRA }) |df| {
        if (c.df == df) {
            for (0..h) |y| yuv2rgbRow(df, &c.tabs, d.row(0, y), s.row(0, y), s.row(1, y >> vs), s.row(2, y >> vs), w);
            return;
        }
    }
}

// ── BGR24 -> YUV420P (ff_rgb24toyv12_c) ─────────────────────────────────────

pub fn bgr24ToYv12(c: *m.Ctx, s: m.Planes, d: m.DPlanes) void {
    const t = &c.tabs;
    const w: usize = @intCast(c.dw);
    const h: usize = @intCast(c.dh);
    const cw = w >> 1;
    var y: usize = 0;
    while (y < h) : (y += 2) {
        const s1 = s.row(0, y);
        const s2 = s.row(0, y + 1);
        const y1 = d.row(0, y);
        const y2 = d.row(0, y + 1);
        const ud = d.row(1, y >> 1);
        const vd = d.row(2, y >> 1);
        for (0..cw) |i| {
            const b11: i32 = s1[6 * i + 0];
            const g11: i32 = s1[6 * i + 1];
            const r11: i32 = s1[6 * i + 2];
            const b12: i32 = s1[6 * i + 3];
            const g12: i32 = s1[6 * i + 4];
            const r12: i32 = s1[6 * i + 5];
            const b21: i32 = s2[6 * i + 0];
            const g21: i32 = s2[6 * i + 1];
            const r21: i32 = s2[6 * i + 2];
            const b22: i32 = s2[6 * i + 3];
            const g22: i32 = s2[6 * i + 4];
            const r22: i32 = s2[6 * i + 5];
            y1[2 * i + 0] = @truncate(@as(u32, @bitCast(((t.ry * r11 + t.gy * g11 + t.by * b11) >> 15) + 16)));
            y1[2 * i + 1] = @truncate(@as(u32, @bitCast(((t.ry * r12 + t.gy * g12 + t.by * b12) >> 15) + 16)));
            y2[2 * i + 0] = @truncate(@as(u32, @bitCast(((t.ry * r21 + t.gy * g21 + t.by * b21) >> 15) + 16)));
            y2[2 * i + 1] = @truncate(@as(u32, @bitCast(((t.ry * r22 + t.gy * g22 + t.by * b22) >> 15) + 16)));
            const bx = (b11 + b12 + b21 + b22) >> 2;
            const gx = (g11 + g12 + g21 + g22) >> 2;
            const rx = (r11 + r12 + r21 + r22) >> 2;
            ud[i] = @truncate(@as(u32, @bitCast(((t.ru * rx + t.gu * gx + t.bu * bx) >> 15) + 128)));
            vd[i] = @truncate(@as(u32, @bitCast(((t.rv * rx + t.gv * gx + t.bv * bx) >> 15) + 128)));
        }
    }
}

// ── byte (de)interleave ─────────────────────────────────────────────────────

pub fn interleave(dst: [*]u8, a: [*]const u8, b: [*]const u8, n: usize) void {
    for (0..n) |i| {
        dst[2 * i] = a[i];
        dst[2 * i + 1] = b[i];
    }
}

pub fn deinterleave(a: [*]u8, b: [*]u8, src: [*]const u8, n: usize) void {
    for (0..n) |i| {
        a[i] = src[2 * i];
        b[i] = src[2 * i + 1];
    }
}

// ── input: packed RGB -> 14-bit Y / U / V / A ───────────────────────────────

fn rgbToYT(comptime sf: i32, dst: [*]i16, src: [*]const u8, w: usize, t: *const Tables) void {
    const sb = comptime bpp(sf);
    for (0..w) |i| {
        const p = src + i * sb;
        const r: i32 = p[comptime rIdx(sf)];
        const g: i32 = p[1];
        const b: i32 = p[comptime bIdx(sf)];
        dst[i] = @truncate((t.ry * r + t.gy * g + t.by * b + (32 << 14) + (1 << 8)) >> 9);
    }
}

fn rgbToUVT(comptime sf: i32, du: [*]i16, dv: [*]i16, src: [*]const u8, w: usize, t: *const Tables) void {
    const sb = comptime bpp(sf);
    for (0..w) |i| {
        const p = src + i * sb;
        const r: i32 = p[comptime rIdx(sf)];
        const g: i32 = p[1];
        const b: i32 = p[comptime bIdx(sf)];
        du[i] = @truncate((t.ru * r + t.gu * g + t.bu * b + (256 << 14) + (1 << 8)) >> 9);
        dv[i] = @truncate((t.rv * r + t.gv * g + t.bv * b + (256 << 14) + (1 << 8)) >> 9);
    }
}

fn rgbToUVHalfT(comptime sf: i32, du: [*]i16, dv: [*]i16, src: [*]const u8, w: usize, t: *const Tables) void {
    const sb = comptime bpp(sf);
    for (0..w) |i| {
        const p = src + 2 * i * sb;
        const r: i32 = @as(i32, p[comptime rIdx(sf)]) + p[sb + comptime rIdx(sf)];
        const g: i32 = @as(i32, p[1]) + p[sb + 1];
        const b: i32 = @as(i32, p[comptime bIdx(sf)]) + p[sb + comptime bIdx(sf)];
        du[i] = @truncate((t.ru * r + t.gu * g + t.bu * b + (256 << 15) + (1 << 9)) >> 10);
        dv[i] = @truncate((t.rv * r + t.gv * g + t.bv * b + (256 << 15) + (1 << 9)) >> 10);
    }
}

pub fn rgbToY(sf: i32, dst: [*]i16, src: [*]const u8, w: usize, t: *const Tables) void {
    switch (sf) {
        inline m.RGB24, m.BGR24, m.RGBA, m.BGRA => |f| rgbToYT(f, dst, src, w, t),
        else => unreachable,
    }
}
pub fn rgbToUV(sf: i32, du: [*]i16, dv: [*]i16, src: [*]const u8, w: usize, t: *const Tables) void {
    switch (sf) {
        inline m.RGB24, m.BGR24, m.RGBA, m.BGRA => |f| rgbToUVT(f, du, dv, src, w, t),
        else => unreachable,
    }
}
pub fn rgbToUVHalf(sf: i32, du: [*]i16, dv: [*]i16, src: [*]const u8, w: usize, t: *const Tables) void {
    switch (sf) {
        inline m.RGB24, m.BGR24, m.RGBA, m.BGRA => |f| rgbToUVHalfT(f, du, dv, src, w, t),
        else => unreachable,
    }
}
pub fn rgbToA(sf: i32, dst: [*]i16, src: [*]const u8, w: usize) void {
    _ = sf;
    for (0..w) |i| {
        const a: i16 = src[4 * i + 3];
        dst[i] = (a << 6) | (a >> 2);
    }
}

// ── horizontal scalers ──────────────────────────────────────────────────────

pub fn hscale8(dst: [*]i16, src: [*]const u8, f: *const filter.Filter, dw: usize) void {
    if (f.identity) {
        for (0..dw) |i| dst[i] = @as(i16, src[i]) << 7;
        return;
    }
    const fs = f.size;
    for (0..dw) |i| {
        const p: usize = @intCast(f.pos[i]);
        var val: i32 = 0;
        for (0..fs) |j| val +%= @as(i32, src[p + j]) * f.coef[fs * i + j];
        dst[i] = @truncate(@min(val >> 7, (1 << 15) - 1));
    }
}

pub fn hscale16(dst: [*]i16, src: [*]const i16, f: *const filter.Filter, dw: usize) void {
    if (f.identity) {
        for (0..dw) |i| dst[i] = @truncate(@min(@as(i32, src[i]) * 2, (1 << 15) - 1));
        return;
    }
    const fs = f.size;
    for (0..dw) |i| {
        const p: usize = @intCast(f.pos[i]);
        var val: i32 = 0;
        for (0..fs) |j| val +%= @as(i32, @as(u16, @bitCast(src[p + j]))) * f.coef[fs * i + j];
        dst[i] = @truncate(@min(val >> 13, (1 << 15) - 1));
    }
}

// ── vertical scalers to 8-bit planes ────────────────────────────────────────

inline fn clipU8(v: i32) u8 {
    return @intCast(std.math.clamp(v, 0, 255));
}

pub fn vplane(dst: [*]u8, rows: []const [*]const i16, coef: []const i16, w: usize) void {
    if (rows.len == 1) {
        const r = rows[0];
        for (0..w) |i| dst[i] = clipU8((@as(i32, r[i]) + 64) >> 7);
        return;
    }
    for (0..w) |i| {
        var val: i32 = 64 << 12;
        for (rows, coef) |r, cf| val +%= @as(i32, r[i]) * cf;
        dst[i] = clipU8(val >> 19);
    }
}

pub fn vnv(dst: [*]u8, a: []const [*]const i16, b: []const [*]const i16, coef: []const i16, w: usize) void {
    for (0..w) |i| {
        var u: i32 = 64 << 12;
        var v: i32 = 64 << 12;
        for (a, b, coef) |ra, rb, cf| {
            u +%= @as(i32, ra[i]) * cf;
            v +%= @as(i32, rb[i]) * cf;
        }
        dst[2 * i] = clipU8(u >> 19);
        dst[2 * i + 1] = clipU8(v >> 19);
    }
}

// ── packed RGB output ───────────────────────────────────────────────────────

inline fn clipP30(v: i32) i32 {
    if ((v & ~@as(i32, (1 << 30) - 1)) != 0) return (~v >> 31) & ((1 << 30) - 1);
    return v;
}

inline fn writeFull(comptime df: i32, t: *const Tables, d: [*]u8, Y0: i32, U: i32, V: i32, A: i32, hasA: bool) void {
    var Y = (Y0 -% t.yoff) *% t.ycoef;
    Y +%= 1 << 21;
    var R = Y +% V *% t.v2r;
    var G = Y +% V *% t.v2g +% U *% t.u2g;
    var B = Y +% U *% t.u2b;
    if (((R | G | B) & @as(i32, @bitCast(@as(u32, 0xC0000000)))) != 0) {
        R = clipP30(R);
        G = clipP30(G);
        B = clipP30(B);
    }
    d[comptime rIdx(df)] = @truncate(@as(u32, @bitCast(R)) >> 22);
    d[1] = @truncate(@as(u32, @bitCast(G)) >> 22);
    d[comptime bIdx(df)] = @truncate(@as(u32, @bitCast(B)) >> 22);
    if (comptime bpp(df) == 4) d[3] = if (hasA) @truncate(@as(u32, @bitCast(A))) else 255;
}

inline fn clipIf100(a: i32) i32 {
    return if ((a & 0x100) != 0) std.math.clamp(a, 0, 255) else a;
}

inline fn tabIdx(i: i32) usize {
    return @intCast(std.math.clamp(i, 0, 2047));
}

inline fn writeHalf(comptime df: i32, t: *const Tables, d: [*]u8, Y1: i32, Y2: i32, U0: i32, V0: i32, A1: i32, A2: i32, hasA: bool) void {
    const U: usize = @intCast(std.math.clamp(U0, 0, 255));
    const V: usize = @intCast(std.math.clamp(V0, 0, 255));
    const ro = t.rOff[V];
    const go = t.gU[U] + t.gV[V];
    const bo = t.bOff[U];
    const db = comptime bpp(df);
    d[comptime rIdx(df)] = t.ytab[tabIdx(Y1 + ro)];
    d[1] = t.ytab[tabIdx(Y1 + go)];
    d[comptime bIdx(df)] = t.ytab[tabIdx(Y1 + bo)];
    d[db + comptime rIdx(df)] = t.ytab[tabIdx(Y2 + ro)];
    d[db + 1] = t.ytab[tabIdx(Y2 + go)];
    d[db + comptime bIdx(df)] = t.ytab[tabIdx(Y2 + bo)];
    if (db == 4) {
        d[3] = if (hasA) @truncate(@as(u32, @bitCast(A1))) else 255;
        d[7] = if (hasA) @truncate(@as(u32, @bitCast(A2))) else 255;
    }
}

fn packed1T(comptime df: i32, c: *m.Ctx, dst: [*]u8, b0: [*]const i16, ub: []const [*]const i16, vb: []const [*]const i16, ab: ?[*]const i16, dw: usize, uvalpha: i32) void {
    const t = &c.tabs;
    const db = comptime bpp(df);
    const hasA = ab != null;
    if (c.fullChr) {
        for (0..dw) |i| {
            const Y = @as(i32, b0[i]) * 4;
            var U: i32 = undefined;
            var V: i32 = undefined;
            if (uvalpha < 2048) {
                U = (@as(i32, ub[0][i]) - (128 << 7)) * 4;
                V = (@as(i32, vb[0][i]) - (128 << 7)) * 4;
            } else {
                U = (@as(i32, ub[0][i]) + ub[1][i] - (128 << 8)) * 2;
                V = (@as(i32, vb[0][i]) + vb[1][i] - (128 << 8)) * 2;
            }
            var A: i32 = 0;
            if (ab) |a| A = clipIf100((@as(i32, a[i]) + 64) >> 7);
            writeFull(df, t, dst + i * db, Y, U, V, A, hasA);
        }
    } else {
        for (0..(dw + 1) >> 1) |i| {
            const Y1 = (@as(i32, b0[2 * i]) + 64) >> 7;
            const Y2 = (@as(i32, b0[2 * i + 1]) + 64) >> 7;
            var U: i32 = undefined;
            var V: i32 = undefined;
            var A1: i32 = 0;
            var A2: i32 = 0;
            if (uvalpha < 2048) {
                U = (@as(i32, ub[0][i]) + 64) >> 7;
                V = (@as(i32, vb[0][i]) + 64) >> 7;
                if (ab) |a| {
                    A1 = std.math.clamp((@as(i32, a[2 * i]) * 255 + 16384) >> 15, 0, 255);
                    A2 = std.math.clamp((@as(i32, a[2 * i + 1]) * 255 + 16384) >> 15, 0, 255);
                }
            } else {
                U = (@as(i32, ub[0][i]) + ub[1][i] + 128) >> 8;
                V = (@as(i32, vb[0][i]) + vb[1][i] + 128) >> 8;
                if (ab) |a| {
                    A1 = std.math.clamp((@as(i32, a[2 * i]) + 64) >> 7, 0, 255);
                    A2 = std.math.clamp((@as(i32, a[2 * i + 1]) + 64) >> 7, 0, 255);
                }
            }
            writeHalf(df, t, dst + 2 * i * db, Y1, Y2, U, V, A1, A2, hasA);
        }
    }
}

fn packed2T(comptime df: i32, c: *m.Ctx, dst: [*]u8, b: []const [*]const i16, ub: []const [*]const i16, vb: []const [*]const i16, ab: ?[]const [*]const i16, dw: usize, yalpha: i32, uvalpha: i32) void {
    const t = &c.tabs;
    const db = comptime bpp(df);
    const hasA = ab != null;
    const ya1 = 4096 - yalpha;
    const uva1 = 4096 - uvalpha;
    if (c.fullChr) {
        for (0..dw) |i| {
            const Y = (@as(i32, b[0][i]) * ya1 + @as(i32, b[1][i]) * yalpha) >> 10;
            const U = (@as(i32, ub[0][i]) * uva1 + @as(i32, ub[1][i]) * uvalpha - (128 << 19)) >> 10;
            const V = (@as(i32, vb[0][i]) * uva1 + @as(i32, vb[1][i]) * uvalpha - (128 << 19)) >> 10;
            var A: i32 = 0;
            if (ab) |a| A = clipIf100((@as(i32, a[0][i]) * ya1 + @as(i32, a[1][i]) * yalpha + (1 << 18)) >> 19);
            writeFull(df, t, dst + i * db, Y, U, V, A, hasA);
        }
    } else {
        for (0..(dw + 1) >> 1) |i| {
            const Y1 = (@as(i32, b[0][2 * i]) * ya1 + @as(i32, b[1][2 * i]) * yalpha) >> 19;
            const Y2 = (@as(i32, b[0][2 * i + 1]) * ya1 + @as(i32, b[1][2 * i + 1]) * yalpha) >> 19;
            const U = (@as(i32, ub[0][i]) * uva1 + @as(i32, ub[1][i]) * uvalpha) >> 19;
            const V = (@as(i32, vb[0][i]) * uva1 + @as(i32, vb[1][i]) * uvalpha) >> 19;
            var A1: i32 = 0;
            var A2: i32 = 0;
            if (ab) |a| {
                A1 = std.math.clamp((@as(i32, a[0][2 * i]) * ya1 + @as(i32, a[1][2 * i]) * yalpha) >> 19, 0, 255);
                A2 = std.math.clamp((@as(i32, a[0][2 * i + 1]) * ya1 + @as(i32, a[1][2 * i + 1]) * yalpha) >> 19, 0, 255);
            }
            writeHalf(df, t, dst + 2 * i * db, Y1, Y2, U, V, A1, A2, hasA);
        }
    }
}

fn packedXT(comptime df: i32, c: *m.Ctx, dst: [*]u8, lr: []const [*]const i16, lc: []const i16, ur: []const [*]const i16, vr: []const [*]const i16, cc: []const i16, ar: ?[]const [*]const i16, dw: usize) void {
    const t = &c.tabs;
    const db = comptime bpp(df);
    const hasA = ar != null;
    if (c.fullChr) {
        for (0..dw) |i| {
            var Y: i32 = 1 << 9;
            var U: i32 = (1 << 9) - (128 << 19);
            var V: i32 = (1 << 9) - (128 << 19);
            for (lr, lc) |r, f| Y +%= @as(i32, r[i]) * f;
            for (ur, vr, cc) |ru, rv, f| {
                U +%= @as(i32, ru[i]) * f;
                V +%= @as(i32, rv[i]) * f;
            }
            Y >>= 10;
            U >>= 10;
            V >>= 10;
            var A: i32 = 0;
            if (ar) |a| {
                A = 1 << 18;
                for (a, lc) |r, f| A +%= @as(i32, r[i]) * f;
                A = clipIf100(A >> 19);
            }
            writeFull(df, t, dst + i * db, Y, U, V, A, hasA);
        }
    } else {
        for (0..(dw + 1) >> 1) |i| {
            var Y1: i32 = 1 << 18;
            var Y2: i32 = 1 << 18;
            var U: i32 = 1 << 18;
            var V: i32 = 1 << 18;
            for (lr, lc) |r, f| {
                Y1 +%= @as(i32, r[2 * i]) * f;
                Y2 +%= @as(i32, r[2 * i + 1]) * f;
            }
            for (ur, vr, cc) |ru, rv, f| {
                U +%= @as(i32, ru[i]) * f;
                V +%= @as(i32, rv[i]) * f;
            }
            Y1 >>= 19;
            Y2 >>= 19;
            U >>= 19;
            V >>= 19;
            var A1: i32 = 0;
            var A2: i32 = 0;
            if (ar) |a| {
                A1 = 1 << 18;
                A2 = 1 << 18;
                for (a, lc) |r, f| {
                    A1 +%= @as(i32, r[2 * i]) * f;
                    A2 +%= @as(i32, r[2 * i + 1]) * f;
                }
                A1 >>= 19;
                A2 >>= 19;
                if (((A1 | A2) & 0x100) != 0) {
                    A1 = std.math.clamp(A1, 0, 255);
                    A2 = std.math.clamp(A2, 0, 255);
                }
            }
            writeHalf(df, t, dst + 2 * i * db, Y1, Y2, U, V, A1, A2, hasA);
        }
    }
}

pub fn packed1(c: *m.Ctx, dst: [*]u8, b0: [*]const i16, ub: []const [*]const i16, vb: []const [*]const i16, ab: ?[*]const i16, dw: usize, uvalpha: i32) void {
    switch (c.df) {
        inline m.RGB24, m.BGR24, m.RGBA, m.BGRA => |f| packed1T(f, c, dst, b0, ub, vb, ab, dw, uvalpha),
        else => unreachable,
    }
}
pub fn packed2(c: *m.Ctx, dst: [*]u8, b: []const [*]const i16, ub: []const [*]const i16, vb: []const [*]const i16, ab: ?[]const [*]const i16, dw: usize, yalpha: i32, uvalpha: i32) void {
    switch (c.df) {
        inline m.RGB24, m.BGR24, m.RGBA, m.BGRA => |f| packed2T(f, c, dst, b, ub, vb, ab, dw, yalpha, uvalpha),
        else => unreachable,
    }
}
pub fn packedX(c: *m.Ctx, dst: [*]u8, lr: []const [*]const i16, lc: []const i16, ur: []const [*]const i16, vr: []const [*]const i16, cc: []const i16, ar: ?[]const [*]const i16, dw: usize) void {
    switch (c.df) {
        inline m.RGB24, m.BGR24, m.RGBA, m.BGRA => |f| packedXT(f, c, dst, lr, lc, ur, vr, cc, ar, dw),
        else => unreachable,
    }
}

