// simd.zig — @Vector helpers: unaligned loads/stores and packed-pixel
// (de)interleaving via @shuffle.

const std = @import("std");

pub const VL = 16;
pub const U8V = @Vector(VL, u8);
pub const I16V = @Vector(VL, i16);
pub const I32V = @Vector(VL, i32);

pub inline fn load(comptime T: type, comptime n: usize, p: [*]const T) @Vector(n, T) {
    return @as(*align(1) const [n]T, @ptrCast(p)).*;
}
pub inline fn store(comptime T: type, comptime n: usize, p: [*]T, v: @Vector(n, T)) void {
    @as(*align(1) [n]T, @ptrCast(p)).* = v;
}
pub inline fn splat(comptime T: type, comptime n: usize, v: T) @Vector(n, T) {
    return @splat(v);
}

pub fn bpp(comptime f: i32) usize {
    return switch (f) {
        5, 6 => 3,
        7, 8 => 4,
        else => 1,
    };
}
pub fn rIdx(comptime f: i32) usize {
    return switch (f) {
        5, 7 => 0,
        else => 2,
    };
}
pub fn bIdx(comptime f: i32) usize {
    return 2 - rIdx(f);
}

fn chanMask(comptime n: usize, comptime stride: usize, comptime off: usize) @Vector(n, i32) {
    var mm: [n]i32 = undefined;
    for (0..n) |i| mm[i] = @intCast(i * stride + off);
    return mm;
}

pub const Pix = struct { r: U8V, g: U8V, b: U8V, a: U8V };

/// Load VL packed pixels of format f and split into channels.
pub inline fn loadPix(comptime f: i32, p: [*]const u8) Pix {
    const sb = comptime bpp(f);
    const raw = load(u8, VL * sb, p);
    var px: Pix = undefined;
    px.r = @shuffle(u8, raw, undefined, comptime chanMask(VL, sb, rIdx(f)));
    px.g = @shuffle(u8, raw, undefined, comptime chanMask(VL, sb, 1));
    px.b = @shuffle(u8, raw, undefined, comptime chanMask(VL, sb, bIdx(f)));
    px.a = if (sb == 4) @shuffle(u8, raw, undefined, comptime chanMask(VL, sb, 3)) else @splat(255);
    return px;
}

fn concatMask(comptime n: usize) @Vector(2 * n, i32) {
    var mm: [2 * n]i32 = undefined;
    for (0..n) |i| {
        mm[i] = @intCast(i);
        mm[n + i] = ~@as(i32, @intCast(i));
    }
    return mm;
}

fn pack3Mask(comptime f: i32) @Vector(3 * VL, i32) {
    // first operand: r ++ g (0..15 r, 16..31 g); second operand: b
    var mm: [3 * VL]i32 = undefined;
    for (0..VL) |i| {
        const ii: i32 = @intCast(i);
        mm[3 * i + rIdx(f)] = ii;
        mm[3 * i + 1] = VL + ii;
        mm[3 * i + bIdx(f)] = ~ii;
    }
    return mm;
}
fn pack4Mask(comptime f: i32) @Vector(4 * VL, i32) {
    // first: r ++ g, second: b ++ a
    var mm: [4 * VL]i32 = undefined;
    for (0..VL) |i| {
        const ii: i32 = @intCast(i);
        mm[4 * i + rIdx(f)] = ii;
        mm[4 * i + 1] = VL + ii;
        mm[4 * i + bIdx(f)] = ~ii;
        mm[4 * i + 3] = ~(VL + ii);
    }
    return mm;
}

/// Interleave channels into VL packed pixels of format f and store.
pub inline fn storePix(comptime f: i32, p: [*]u8, r: U8V, g: U8V, b: U8V, a: U8V) void {
    const db = comptime bpp(f);
    const rg = @shuffle(u8, r, g, comptime concatMask(VL));
    if (db == 3) {
        const out = @shuffle(u8, rg, b, comptime pack3Mask(f));
        store(u8, 3 * VL, p, out);
    } else {
        const ba = @shuffle(u8, b, a, comptime concatMask(VL));
        const out = @shuffle(u8, rg, ba, comptime pack4Mask(f));
        store(u8, 4 * VL, p, out);
    }
}

pub inline fn clampU8(v: I32V) U8V {
    const lo: I32V = @splat(0);
    const hi: I32V = @splat(255);
    return @intCast(@min(@max(v, lo), hi));
}
pub inline fn clampU8w(v: I16V) U8V {
    const lo: I16V = @splat(0);
    const hi: I16V = @splat(255);
    return @intCast(@min(@max(v, lo), hi));
}

fn dupMask(comptime n: usize) @Vector(n, i32) {
    var mm: [n]i32 = undefined;
    for (0..n) |i| mm[i] = @intCast(i / 2);
    return mm;
}
/// Duplicate each of the first VL/2 elements: [a,b,c..] -> [a,a,b,b,c,c..]
pub inline fn dup2(comptime T: type, v: @Vector(VL / 2, T)) @Vector(VL, T) {
    return @shuffle(T, v, undefined, comptime dupMask(VL));
}

fn evenMask(comptime n: usize, comptime off: usize) @Vector(n, i32) {
    var mm: [n]i32 = undefined;
    for (0..n) |i| mm[i] = @intCast(2 * i + off);
    return mm;
}
pub inline fn evens(comptime T: type, comptime n: usize, v: @Vector(2 * n, T)) @Vector(n, T) {
    return @shuffle(T, v, undefined, comptime evenMask(n, 0));
}
pub inline fn odds(comptime T: type, comptime n: usize, v: @Vector(2 * n, T)) @Vector(n, T) {
    return @shuffle(T, v, undefined, comptime evenMask(n, 1));
}
fn ilvMask(comptime n: usize) @Vector(2 * n, i32) {
    var mm: [2 * n]i32 = undefined;
    for (0..n) |i| {
        mm[2 * i] = @intCast(i);
        mm[2 * i + 1] = ~@as(i32, @intCast(i));
    }
    return mm;
}
pub inline fn interleave2(comptime T: type, comptime n: usize, a: @Vector(n, T), b: @Vector(n, T)) @Vector(2 * n, T) {
    return @shuffle(T, a, b, comptime ilvMask(n));
}

