new='''fn rgbToYT(comptime sf: i32, dst: [*]i16, src: [*]const u8, w: usize, t: *const Tables) void {
    const sb = comptime bpp(sf);
    const V = S.I32V;
    const ry: V = @splat(t.ry);
    const gy: V = @splat(t.gy);
    const by: V = @splat(t.by);
    const k0: V = @splat((32 << 14) + (1 << 8));
    var i: usize = 0;
    while (i + S.VL <= w) : (i += S.VL) {
        const px = S.loadPix(sf, src + i * sb);
        const r: V = px.r;
        const g: V = px.g;
        const b: V = px.b;
        const y = (ry * r + gy * g + by * b + k0) >> @splat(9);
        S.store(i16, S.VL, dst + i, @truncate(y));
    }
    while (i < w) : (i += 1) {
        const p = src + i * sb;
        const r: i32 = p[comptime rIdx(sf)];
        const g: i32 = p[1];
        const b: i32 = p[comptime bIdx(sf)];
        dst[i] = @truncate((t.ry * r + t.gy * g + t.by * b + (32 << 14) + (1 << 8)) >> 9);
    }
}

fn rgbToUVT(comptime sf: i32, du: [*]i16, dv: [*]i16, src: [*]const u8, w: usize, t: *const Tables) void {
    const sb = comptime bpp(sf);
    const V = S.I32V;
    const k0: V = @splat((256 << 14) + (1 << 8));
    var i: usize = 0;
    while (i + S.VL <= w) : (i += S.VL) {
        const px = S.loadPix(sf, src + i * sb);
        const r: V = px.r;
        const g: V = px.g;
        const b: V = px.b;
        const u = (@as(V, @splat(t.ru)) * r + @as(V, @splat(t.gu)) * g + @as(V, @splat(t.bu)) * b + k0) >> @splat(9);
        const v = (@as(V, @splat(t.rv)) * r + @as(V, @splat(t.gv)) * g + @as(V, @splat(t.bv)) * b + k0) >> @splat(9);
        S.store(i16, S.VL, du + i, @truncate(u));
        S.store(i16, S.VL, dv + i, @truncate(v));
    }
    while (i < w) : (i += 1) {
        const p = src + i * sb;
        const r: i32 = p[comptime rIdx(sf)];
        const g: i32 = p[1];
        const b: i32 = p[comptime bIdx(sf)];
        du[i] = @truncate((t.ru * r + t.gu * g + t.bu * b + (256 << 14) + (1 << 8)) >> 9);
        dv[i] = @truncate((t.rv * r + t.gv * g + t.bv * b + (256 << 14) + (1 << 8)) >> 9);
