    const db = comptime bpp(df);
    if (sf == df) {
        @memcpy(dst[0 .. w * sb], src[0 .. w * sb]);
        return;
    }
    var x: usize = 0;
    while (x + S.VL <= w) : (x += S.VL) {
        const px = S.loadPix(sf, src + x * sb);
        S.storePix(df, dst + x * db, px.r, px.g, px.b, px.a);
    }
    while (x < w) : (x += 1) {
        const s_ = src + x * sb;
        const d = dst + x * db;
        d[comptime rIdx(df)] = s_[comptime rIdx(sf)];
        d[1] = s_[1];
        d[comptime bIdx(df)] = s_[comptime bIdx(sf)];
        if (db == 4) d[3] = if (sb == 4) s_[3] else 255;
    }
}

