# yuv2rgb unscaled
i=s.index('fn yuv2rgbRow(')
j=s.index('pub fn yuv2rgbTable(')
s=s[:i]+'''fn yuv2rgbRow(comptime df: i32, t: *const Tables, dst: [*]u8, py: [*]const u8, pu: [*]const u8, pv: [*]const u8, w: usize) void {
    const db = comptime bpp(df);
    const V = S.I32V;
    const cyv: V = @splat(t.cy);
    const yb: V = @splat(t.ybase);
    var x: usize = 0;
    // chroma loads read VL bytes at x/2: stay VL/2 pixels clear of the row end
    while (x + 2 * S.VL <= w + S.VL / 2 and x + S.VL <= w) : (x += S.VL) {
        const yv: V = S.load(u8, S.VL, py + x);
        const u: V = S.load(u8, S.VL, pu + x / 2);
        const v: V = S.load(u8, S.VL, pv + x / 2);
        const ro = @as(V, @splat(t.rK)) + ((v * @as(V, @splat(t.crv))) >> @splat(16));
        const go = @as(V, @splat(t.gK)) + ((u * @as(V, @splat(t.cgu))) >> @splat(16)) + ((v * @as(V, @splat(t.cgv))) >> @splat(16));
        const bo = @as(V, @splat(t.bK)) + ((u * @as(V, @splat(t.cbu))) >> @splat(16));
        const yc = yv * cyv + yb;
        const R = S.clampU8((yc + S.dup2(i32, ro * cyv)) >> @splat(16));
        const G = S.clampU8((yc + S.dup2(i32, go * cyv)) >> @splat(16));
        const B = S.clampU8((yc + S.dup2(i32, bo * cyv)) >> @splat(16));
        S.storePix(df, dst + x * db, R, G, B, @splat(255));
    }
    while (x < w) : (x += 1) {
        const Y: i32 = py[x];
        const U = pu[x >> 1];
        const Vv = pv[x >> 1];
        const d = dst + x * db;
        d[comptime rIdx(df)] = t.ytab[@intCast(Y + t.rOff[Vv])];
        d[1] = t.ytab[@intCast(Y + t.gU[U] + t.gV[Vv])];
        d[comptime bIdx(df)] = t.ytab[@intCast(Y + t.bOff[U])];
        if (db == 4) d[3] = 255;
    }
}

