j=s.index('// ── input: packed RGB')
s=s[:i]+'''pub fn interleave(dst: [*]u8, a: [*]const u8, b: [*]const u8, n: usize) void {
    var i: usize = 0;
    while (i + 32 <= n) : (i += 32) {
        S.store(u8, 64, dst + 2 * i, S.interleave2(u8, 32, S.load(u8, 32, a + i), S.load(u8, 32, b + i)));
    }
    while (i < n) : (i += 1) {
        dst[2 * i] = a[i];
        dst[2 * i + 1] = b[i];
    }
}

pub fn deinterleave(a: [*]u8, b: [*]u8, src: [*]const u8, n: usize) void {
    var i: usize = 0;
    while (i + 32 <= n) : (i += 32) {
        const h = S.deinterleave2(u8, 32, S.load(u8, 64, src + 2 * i));
        S.store(u8, 32, a + i, h[0]);
        S.store(u8, 32, b + i, h[1]);
    }
    while (i < n) : (i += 1) {
        a[i] = src[2 * i];
        b[i] = src[2 * i + 1];
    }
}

