fused='''// Fused full-chroma output: vertical mix + YUV->RGB per 16-pixel block, no row temporaries.
const FSrc = struct {
    mode: u8, // 0: 1-tap (uv0), 1: 1-tap (uv avg), 2: 2-tap blend, 3: X taps
    lr: []const [*]const i16,
    lc: []const i16,
    ur: []const [*]const i16,
    vr: []const [*]const i16,
    cc: []const i16,
    ar: ?[]const [*]const i16,
    ya: i32,
    uva: i32,
};

inline fn ld(r: [*]const i16, i: usize) S.I32V {
    return S.load(i16, S.VL, r + i);
}

inline fn selClip100(a: S.I32V) S.I32V {
    const m = (a & @as(S.I32V, @splat(0x100))) != @as(S.I32V, @splat(0));
    return @select(i32, m, @min(@max(a, @as(S.I32V, @splat(0))), @as(S.I32V, @splat(255))), a);
}

inline fn fullVals(comptime mode: u8, comptime hasA: bool, f: *const FSrc, i: usize) [4]S.I32V {
    const V = S.I32V;
    var y: V = undefined;
    var u: V = undefined;
    var v: V = undefined;
    var a: V = @splat(255);
    switch (mode) {
        0 => {
            y = ld(f.lr[0], i) * @as(V, @splat(4));
            u = (ld(f.ur[0], i) - @as(V, @splat(128 << 7))) * @as(V, @splat(4));
            v = (ld(f.vr[0], i) - @as(V, @splat(128 << 7))) * @as(V, @splat(4));
            if (hasA) a = selClip100((ld(f.ar.?[0], i) + @as(V, @splat(64))) >> @splat(7));
        },
        1 => {
            y = ld(f.lr[0], i) * @as(V, @splat(4));
            u = (ld(f.ur[0], i) + ld(f.ur[1], i) - @as(V, @splat(128 << 8))) * @as(V, @splat(2));
            v = (ld(f.vr[0], i) + ld(f.vr[1], i) - @as(V, @splat(128 << 8))) * @as(V, @splat(2));
            if (hasA) a = selClip100((ld(f.ar.?[0], i) + @as(V, @splat(64))) >> @splat(7));
        },
        2 => {
            const ya: V = @splat(f.ya);
            const ya1: V = @splat(4096 - f.ya);
            const uva: V = @splat(f.uva);
            const uva1: V = @splat(4096 - f.uva);
            y = (ld(f.lr[0], i) * ya1 + ld(f.lr[1], i) * ya) >> @splat(10);
            u = (ld(f.ur[0], i) * uva1 + ld(f.ur[1], i) * uva - @as(V, @splat(128 << 19))) >> @splat(10);
            v = (ld(f.vr[0], i) * uva1 + ld(f.vr[1], i) * uva - @as(V, @splat(128 << 19))) >> @splat(10);
            if (hasA) a = selClip100((ld(f.ar.?[0], i) * ya1 + ld(f.ar.?[1], i) * ya + @as(V, @splat(1 << 18))) >> @splat(19));
        },
        else => {
            y = @splat(1 << 9);
            u = @splat((1 << 9) - (128 << 19));
            v = u;
            for (f.lr, f.lc) |r, cf| y +%= ld(r, i) *% @as(V, @splat(@as(i32, cf)));
            for (f.ur, f.vr, f.cc) |ru, rv, cf| {
                const cv: V = @splat(@as(i32, cf));
                u +%= ld(ru, i) *% cv;
                v +%= ld(rv, i) *% cv;
            }
            y >>= @splat(10);
            u >>= @splat(10);
            v >>= @splat(10);
            if (hasA) {
                var aa: V = @splat(1 << 18);
                for (f.ar.?, f.lc) |r, cf| aa +%= ld(r, i) *% @as(V, @splat(@as(i32, cf)));
                a = selClip100(aa >> @splat(19));
            }
        },
    }
    return .{ y, u, v, a };
}

fn fusedFullT(comptime df: i32, comptime mode: u8, comptime hasA: bool, t: *const Tables, dst: [*]u8, f: *const FSrc, w: usize) void {
    const db = comptime bpp(df);
    const V = S.I32V;
    const yoff: V = @splat(t.yoff);
    const ycoef: V = @splat(t.ycoef);
    const v2r: V = @splat(t.v2r);
    const v2g: V = @splat(t.v2g);
    const u2g: V = @splat(t.u2g);
    const u2b: V = @splat(t.u2b);
    const lo: V = @splat(0);
    const hi: V = @splat((1 << 30) - 1);
    var i: usize = 0;
    while (i < w) : (i += S.VL) {
        const q = fullVals(mode, hasA, f, i);
        const y = (q[0] -% yoff) *% ycoef +% @as(V, @splat(1 << 21));
        const R: S.U8V = @intCast(@min(@max(y +% q[2] *% v2r, lo), hi) >> @splat(22));
        const G: S.U8V = @intCast(@min(@max(y +% q[2] *% v2g +% q[1] *% u2g, lo), hi) >> @splat(22));
        const B: S.U8V = @intCast(@min(@max(y +% q[1] *% u2b, lo), hi) >> @splat(22));
        const A: S.U8V = @truncate(@as(@Vector(S.VL, u32), @bitCast(q[3])));
        if (i + S.VL <= w) {
            S.storePix(df, dst + i * db, R, G, B, A);
        } else {
            const ra: [S.VL]u8 = R;
            const ga: [S.VL]u8 = G;
            const ba: [S.VL]u8 = B;
            const aa: [S.VL]u8 = A;
            for (0..w - i) |l| {
                const d = dst + (i + l) * db;
                d[comptime rIdx(df)] = ra[l];
                d[1] = ga[l];
                d[comptime bIdx(df)] = ba[l];
                if (db == 4) d[3] = aa[l];
            }
        }
    }
}

fn fusedFull(c: *m.Ctx, dst: [*]u8, f: *const FSrc, dw: usize) void {
    switch (c.df) {
        inline m.RGB24, m.BGR24, m.RGBA, m.BGRA => |df| switch (f.mode) {
            inline 0, 1, 2, 3 => |md| {
                if (f.ar != null) fusedFullT(df, md, true, &c.tabs, dst, f, dw) else fusedFullT(df, md, false, &c.tabs, dst, f, dw);
            },
            else => unreachable,
        },
        else => unreachable,
    }
}

