import sys, os, subprocess, tempfile
sys.path.insert(0, "/app")
import workloads as W
lib = sys.argv[1]
SUB = W.SUBSAMPLED
def run(l, wl, out):
    p = subprocess.run(W.driver_argv("/app/driver", l, wl, 1, out), capture_output=True, text=True)
    if p.returncode != 0: return None
    return open(out, "rb").read()
cases = []
import itertools
sizes_even = [(2, 2), (18, 6), (34, 30), (638, 478), (1282, 722)]
sizes_odd = [(1, 1), (3, 5), (17, 9), (641, 479), (1281, 721)]
for (s, d) in W._PAIRS:
    for (w, h) in sizes_even:
        cases.append(W._wl("x", s, d, w, h, w, h, 1))
    if s not in SUB and d not in SUB:
        for (w, h) in sizes_odd:
            cases.append(W._wl("x", s, d, w, h, w, h, 1))
for (s, d, sw, sh, dw, dh, a) in W._SCALES:
    for f in (0.5, 1.37, 0.77):
        def ev(x): 
            x = max(2, int(x * f)); return x + (x & 1)
        cases.append(W._wl("x", s, d, ev(sw), ev(sh), ev(dw), ev(dh), a))
    if s not in SUB and d not in SUB:
        cases.append(W._wl("x", s, d, sw + 1, sh + 3, dw + 1, dh - 1, a))
        cases.append(W._wl("x", s, d, sw, sh, 3, 2, a))
        cases.append(W._wl("x", s, d, 7, 5, dw // 3 + 1, dh // 5 + 1, a))
bad = 0
tmp = tempfile.mkdtemp()
for wl in cases:
    r = run("/app/libswscale_public_baseline.so", wl, tmp + "/r")
    c = run(lib, wl, tmp + "/c")
    if r is None:
        continue
    if c is None:
        print("CRASH/ERR", wl["label"]); bad += 1; continue
    g = W.grade(r, c, wl["dst_fmt"], wl["dst_w"], wl["dst_h"], wl["scaling"])
    if g["status"] != "pass":
        bad += 1; print("FAIL", wl["label"], g.get("plane_psnr"))
print(len(cases), "cases,", bad, "bad")
