            for (1..nt) |j| acc += ldStride(T, Q, src + b + j) * @as(@Vector(16, i32), @splat(f.ph_coef[p][j]));
            res[p] = @truncate(@min(acc >> @splat(shift), mx));
        }"""
new="""        inline for (0..P) |p| {
            const b: usize = @intCast(@as(i32, @intCast(Q * k0)) + f.ph_base[p]);
            var acc: @Vector(16, i32) = undefined;
            if (Q == 2) {
                // taps (j, j+1) of output k sit at src[2k+b+j], src[2k+b+j+1]: the even/odd
                // lanes of one contiguous load -> multiply-add of adjacent pairs
                acc = @splat(0);
                var j: usize = 0;
                while (j < nt) : (j += 2) {
                    const x: @Vector(32, T) = S.load(T, 32, src + b + j);
                    const xw: @Vector(32, i16) = if (T == u8) @intCast(x) else @bitCast(x);
                    const h = S.deinterleave2(i16, 16, xw);
                    acc += @as(@Vector(16, i32), h[0]) * @as(@Vector(16, i32), @splat(f.ph_coef[p][j])) +
                        @as(@Vector(16, i32), h[1]) * @as(@Vector(16, i32), @splat(f.ph_coef[p][j + 1]));
                }
            } else {
                acc = ldStride(T, Q, src + b) * @as(@Vector(16, i32), @splat(f.ph_coef[p][0]));
                for (1..nt) |j| acc += ldStride(T, Q, src + b + j) * @as(@Vector(16, i32), @splat(f.ph_coef[p][j]));
            }
            res[p] = @truncate(@min(acc >> @splat(shift), mx));
        }"""
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
